88: function definition(task, registry, inventory) {
89:   assert(runtimeTasks.has(task), 'Untrusted Task Context: use createTask or restoreTask');
90:   assert(task.registry_binding === digest(registry), 'Registry changed; explicitly migrate/reselect workflow');
91:   if (task.workflow_id) {
92:     const workflow = registry.workflows[task.workflow_id];
93:     assert(workflow, 'Unknown registered workflow');
94:     return workflow;
95:   }
96:   assert(inventory.has(task.skill_id), 'Unknown single Skill');
97:   return { stages: [{ id: 'task', type: 'skill', skill: task.skill_id, optional: false, condition: 'always', prerequisites: [], next: [], permission: 'request_scoped', stop_conditions: [] }], stop_conditions: [] };
98: }
99: 
100: export function createTask({ id, goal, acceptance, workflow_id = null, skill_id = null }, registry, inventory) {
101:   assert(id && goal && Array.isArray(acceptance) && acceptance.length, 'Goal and acceptance are required');
102:   assert(acceptance.every(item => typeof item === 'string' && item.length) && new Set(acceptance).size === acceptance.length, 'Acceptance IDs must be distinct strings');
103:   assert(Boolean(workflow_id) !== Boolean(skill_id), 'Choose one registered workflow or one existing Skill');
104:   const task = { schema_version: 2, id, goal, acceptance: copy(acceptance), workflow_id, skill_id,
105:     registry_binding: digest(registry), decisions: [], scope: { files: [], modules: [], interfaces: [] },
106:     risks: [], permission_refs: [], evidence: [], changes: [], unresolved: [], next_actions: [],
107:     current_stage: null, steps: {}, history: [] };
108:   runtimeTasks.add(task);
109:   for (const stage of definition(task, registry, inventory).stages) task.steps[stage.id] = { status: 'pending', attempts: 0, evidence_ids: [] };
110:   return task;
111: }
112: 
113: function evidenceFor(task, ids, host) {
114:   return ids?.length > 0 && ids.every(id => {
115:     const evidence = task.evidence.find(e => e.id === id);
116:     return evidence?.task_binding === taskBinding(task) && evidenceValidity(evidence, host).status === 'valid';
117:   });
118: }
119: function condition(task, name, host) {
120:   if (name === 'always') return true;
121:   const fact = host.conditions?.[name];
122:   return fact && typeof fact.value === 'boolean' && fact.reason && evidenceFor(task, fact.evidence_ids, host) ? fact.value : undefined;
123: }
124: function permission(skill, stage, task, host) {
125:   const metadata = host.inventory.get(skill);
126:   if (!metadata || !['draft', 'beta', 'stable'].includes(metadata.status)) return 'skill_unavailable';
127:   const request = host.requests?.[stage.id];
128:   if (!request) return 'operation_scope_missing';
129:   if (!Array.isArray(request.capabilities) || !request.capabilities.length) return 'capabilities_missing';
130:   if (stage.permission === 'write_scoped' && !request.capabilities.includes('write_files')) return 'write_scope_missing';
131:   if (stage.permission === 'read_only' && request.capabilities.includes('write_files')) return 'read_only_stage';
132:   for (const capability of request.capabilities) {
133:     if (!allowedCapabilities.includes(capability) || metadata.permissions?.[capability] !== true
134:         || host.capabilities?.[capability] !== true) return `capability_denied:${capability}`;
135:     const grants = host.grants?.filter(g => g.task_id === task.id && g.capability === capability && g.source
136:       && g.skills.includes(skill)) ?? [];
137:     if (!grants.length) return `user_authorization_missing:${capability}`;
138:     if (['read_files', 'write_files'].includes(capability)) {
139:       if (!request.paths?.length || request.paths.some(p => !safePath(p))) return 'explicit_paths_missing';
140:       if (request.paths.some(p => !grants.some(g => g.paths?.includes(p)))) return `path_not_authorized:${capability}`;
141:       try { for (const p of request.paths) checkPath(host.root, p); } catch { return 'unsafe_path'; }
142:     } else if (!request.operation || !grants.some(g => g.operations?.includes(request.operation))) return `operation_not_authorized:${capability}`;
143:   }
144:   const check = host.skillChecks?.[stage.id];
145:   if (!check?.source || check.request_binding !== digest(request) || check.skill_binding !== digest(metadata) || check.allowed !== true) return 'skill_scope_not_verified';
146:   if (request.capabilities.includes('run_shell_commands') && request.preflight !== 'safe') return 'command_preflight_missing';
147:   return null;
148: }
149: 
150: function writes(stage, host) {
151:   return stage.permission === 'write_scoped' || (stage.permission === 'request_scoped' && host.requests?.[stage.id]?.capabilities?.includes('write_files'));
152: }
153: 
154: export function reconciliationBinding(task, stageId, host) {
155:   return digest({ intent: taskBinding(task), stage: stageId, step: task.steps[stageId], request: host.requests?.[stageId] });
156: }
157: 
158: export function recoveryBinding(task, host) {
159:   const checkpoint = recovered.get(task);
160:   return checkpoint ? digest({ checkpoint, intent: taskBinding(task), requests: host.requests, skillChecks: host.skillChecks }) : null;
161: }
162: 
163: function requirement(task, requirement, host) {
164:   return task.evidence.some(e => e.claims?.includes(requirement.claim)
165:     && e.task_binding === taskBinding(task)
166:     && (!requirement.skill || e.skill === requirement.skill)
167:     && (!requirement.kind || e.kind === requirement.kind)
168:     && (requirement.kind !== 'review' || (e.kind === 'review' && e.independent === true && host.reviewBinding && e.review_basis === host.reviewBinding))
169:     && evidenceValidity(e, host).status === 'valid');
170: }
171: 
172: function stepEvidence(task, stage, host) {
173:   const step = task.steps[stage.id];
174:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
175:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
176:   const scoped = evidence.filter(e => e.skill === stage.skill && e.request_binding === digest(host.requests[stage.id]) && e.claims?.includes(`stage:${stage.id}`));
177:   if (!scoped.length) return false;
178:   if (stage.skill === 'safe-code-review' && !scoped.some(e => e.kind === 'review' && e.independent === true
179:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
180:   if (stage.skill === 'bug-root-cause-analysis' && !scoped.some(e => e.signal_ids?.length
181:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal' && signal.task_binding === taskBinding(task)
182:         && evidenceValidity(signal, host).status === 'valid')))) return false;
183:   return true;
184: }
185: 
186: /** Recompute a decision every time. No imported context field grants execution authority. */
187: export function nextAction(task, host) {
188:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
189:   const workflow = definition(task, host.registry, host.inventory);
190:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
191:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
192:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
193:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
194:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
195:   const recovery = recoveryBinding(task, host);
196:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
197:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
198:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
199:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
200:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
201:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
202:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
203:   const completed = new Set();
204:   for (const stage of workflow.stages) {
205:     const step = task.steps[stage.id];
206:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
207:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
208:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
209:     }
210:     const applies = condition(task, stage.condition, host);
211:     const decision = { stage: stage.id, skill: stage.skill };
212:     const stop = [...(workflow.stop_conditions ?? []), ...stage.stop_conditions]
213:       .find(name => condition(task, name, host) === true);
214:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop}` };
215:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
216:     // Completed effects stay protected even when applicability changes. A new receipt
217:     // is not a reconciliation of the previous attempt's potentially different effects.
218:     const wasCompleted = ['completed', 'reused'].includes(step.status);
219:     const effectful = step.effect_state === 'known' || writes(stage, host)
220:       || host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files');
221:     if (stage.type === 'skill' && wasCompleted) {
222:       const denied = permission(stage.skill, stage, task, host);
223:       if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
224:       if (!stepEvidence(task, stage, host) && effectful) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
225:     }
226:     if (!applies) {
227:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
228:       // Applicability must not erase a completed operation or its known effects.
229:       if (['completed', 'reused'].includes(step.status)) { completed.add(stage.id); continue; }
230:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
231:       completed.add(stage.id); continue;
232:     }
233:     if (stage.type === 'gate') {
234:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
235:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
236:       for (const child of children) {
237:         const denied = permission(child.skill, child, task, host);
238:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
239:       }
240:       // Always re-evaluate gates against host grants, never reuse persisted approval.
241:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
242:       completed.add(stage.id); continue;
243:     }
244:     const denied = permission(stage.skill, stage, task, host);
245:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
246:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
247:       completed.add(stage.id); continue;
248:     }
249:     const failure = step.status === 'validation_failed';
250:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
251:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
252:     if (writes(stage, host)) {
253:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
254:         .find(r => !requirement(task, r, host));
255:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
256:     }
257:     const candidate = host.reuse?.[stage.id];
258:     if (candidate) {
259:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
260:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
261:     }
262:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
263:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
264:     }
265:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
266:   }
267:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
268:   const obligations = [
269:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
270:     ...([...completed].some(id => {
271:       const stage = workflow.stages.find(s => s.id === id);
272:       return task.steps[id].status !== 'skipped'
273:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
274:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
275:     ...(host.deliveryRequirements ?? []),
276:     ...(host.risks ?? []).flatMap(r => {
277:       const rules = host.registry.coordination?.risk_requirements?.[r];
278:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
279:     }),
280:   ];
281:   const missing = obligations.filter(r => !requirement(task, r, host));
282:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
283:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
284: }
