286: function event(task, stage, status, reason) {
287:   task.current_stage = stage;
288:   task.history.push({ sequence: task.history.length + 1, stage, status, reason });
289: }
290: 
291: export function advance(task, host) {
292:   const action = nextAction(task, host);
293:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
294:     const step = task.steps[action.stage];
295:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
296:     step.reason = action.reason;
297:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
298:     if (action.action === 'execute') {
299:       step.attempts++;
300:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
301:     }
302:     if (action.action === 'skip') {
303:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
304:       step.condition_binding = digest(host.conditions[stage.condition]);
305:     }
306:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
307:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
308:     event(task, action.stage, step.status, action.reason);
309:   }
310:   task.next_actions = [action];
311:   return action;
312: }
313: 
314: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
315:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
316:   const step = task.steps[stageId];
317:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
318:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
319:   const denied = permission(stage.skill, stage, task, host);
320:   assert(!denied, denied);
321:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
322:   else {
323:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
324:     assert(stepEvidence(provisional, stage, host), 'Completion requires valid, scoped evidence and independent review');
325:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
326:   }
327:   event(task, stageId, step.status, failureReason || 'observed_completion');
328: }
