330: /** Reopening is an explicit host decision; only descendants are reopened.
331:  * Evidence is retained, so still-valid independent checks can be reused.
332:  */
333: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
334:   assert(reason && source, 'Reopen requires a sourced reason');
335:   const workflow = definition(task, host.registry, host.inventory);
336:   assert(task.steps[stageId], 'Unknown stage');
337:   const affected = new Set([stageId]);
338:   let changed = true;
339:   while (changed) { changed = false; for (const stage of workflow.stages) {
340:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
341:   } }
342:   for (const id of affected) {
343:     const stage = workflow.stages.find(s => s.id === id);
344:     if (['running', 'interrupted'].includes(task.steps[id].status)
345:         || task.steps[id].effect_state === 'uncertain'
346:         || ((writes(stage, host) || task.steps[id].effect_state === 'known' || host.requests?.[id]?.capabilities?.some(c => c !== 'read_files')) && ['completed', 'reused', 'validation_failed'].includes(task.steps[id].status))) {
347:       assert(safeToRetry && host.reconciled?.has(reconciliationBinding(task, id, host)), 'Unknown side effects must be reconciled before retry');
348:     }
349:   }
350:   for (const id of affected) {
351:     const previous = task.steps[id].request_binding;
352:     task.steps[id].status = 'pending'; task.steps[id].effect_state = 'reconciled';
353:     delete task.steps[id].request_binding;
354:     event(task, id, 'pending', `${reason} (${source})`);
355:     if (previous) task.history.at(-1).previous_request_binding = previous;
356:   }
357: }
358: 
359: export function encodeTask(task) { return JSON.stringify(task, null, 2) + '\n'; }
360: export function restoreTask(serialized, registry, inventory) {
361:   const task = JSON.parse(serialized);
362:   assert(task.schema_version === 2 && task.id && task.goal && Array.isArray(task.acceptance) && task.acceptance.length, 'Invalid Task Context');
363:   assert(Boolean(task.workflow_id) !== Boolean(task.skill_id), 'Choose one registered workflow or one existing Skill');
